"""Generate Track B's synthetic expression dataset.

Section 5A of the brief asks for a synthetic feature-by-sample dataset
"generated by a documented, seeded process with a *known* set of truly-shifted
features". This is that process. The ground truth is what makes the Module 16
capstone gradable at all: a learner's pipeline is checked against the features
that were actually shifted, not merely against "it ran".

Run from the repository root:

    python content/datasets/generate.py

It rewrites the CSVs next to this file. They are committed, and a test
(apps/api/tests/test_dataset.py) regenerates them and fails if anything differs
— so the files, this script, and the ground truth cannot drift apart.

The model
---------
Everything is generated on a log2 scale, the way expression data is usually
handed to an analyst. On this scale a difference of 1 means "twice as much",
and the effect of a condition is simply a difference of means.

For feature i in sample j:

    value = baseline_i + shift_i * treated_j + noise_ij + offset_j

- `baseline_i`  how strongly the feature is measured at all.
- `shift_i`     zero for most features; +/- 1.5 to 2.5 for the truly shifted.
- `noise_ij`    biological variability, a different spread per feature.
- `offset_j`    technical variability: some samples read slightly "hot" or
                "cold" across the board. This is what normalisation removes.

Values that fall below a detection limit are recorded as missing, as a real
instrument would. The generator guarantees they occur only in low-signal
features — the ones the pipeline's filtering step removes — so a learner never
has to decide how to test a feature that was mostly not measured.
"""

from __future__ import annotations

from pathlib import Path

import numpy as np
import pandas as pd
from scipy import stats

SEED = 20260922
HERE = Path(__file__).resolve().parent

N_LOW_SIGNAL = 40  # features near the detection limit; removed by filtering
N_NORMAL = 160  # features measured well
N_SHIFTED = 20  # of the normal ones, truly different between conditions
N_PER_CONDITION = 6

DETECTION_LIMIT = 4.0  # log2 units; anything lower is recorded as missing
LOW_SIGNAL_THRESHOLD = 6.0  # the filter every learner applies (Module 13)

# What the pipeline calls a finding (Modules 14 and 16).
ALPHA = 0.05
MIN_EFFECT = 1.0


def generate() -> tuple[pd.DataFrame, pd.DataFrame, pd.DataFrame]:
    rng = np.random.default_rng(SEED)
    n_features = N_LOW_SIGNAL + N_NORMAL
    n_samples = 2 * N_PER_CONDITION

    # Condition order is shuffled rather than "six controls then six treated",
    # so the sample table has to be consulted — which is the lesson Module 11
    # makes about keeping metadata separate from measurements.
    conditions = np.array(["control"] * N_PER_CONDITION + ["treated"] * N_PER_CONDITION)
    rng.shuffle(conditions)
    sample_ids = [f"S{j + 1:02d}" for j in range(n_samples)]
    replicate = {"control": 0, "treated": 0}
    replicates = []
    for condition in conditions:
        replicate[condition] += 1
        replicates.append(replicate[condition])

    feature_ids = [f"gene_{i + 1:03d}" for i in range(n_features)]

    # Low-signal and well-measured features are drawn from separated ranges, so
    # the filter at LOW_SIGNAL_THRESHOLD divides them cleanly. The order is then
    # shuffled so the low-signal ones are not simply the first forty rows.
    baseline = np.concatenate(
        [rng.uniform(2.5, 4.5, N_LOW_SIGNAL), rng.uniform(7.0, 12.0, N_NORMAL)]
    )
    order = rng.permutation(n_features)
    baseline = baseline[order]
    low_signal = np.zeros(n_features, dtype=bool)
    low_signal[order < N_LOW_SIGNAL] = True
    spread = rng.uniform(0.25, 0.5, n_features)

    # Truly shifted features come only from strongly measured ones, so that a
    # down-shift cannot push them under the detection limit.
    candidates = np.flatnonzero(~low_signal & (baseline >= 8.5))
    shifted_idx = rng.choice(candidates, N_SHIFTED, replace=False)

    # Directions alternate in order of baseline, and each up/down pair shares a
    # magnitude. This is not decoration. Median normalisation (Module 13)
    # assumes the real changes are balanced around the middle of each sample;
    # when they are not, the shifted features drag the treated samples' medians
    # and centring on those medians plants a false difference in every
    # unchanged feature. An earlier version of this generator shuffled the
    # directions freely and did exactly that — false positives among the null
    # features doubled after normalisation. Balancing the shifts keeps the
    # reference analysis honest; the lesson states the assumption out loud.
    shifted_idx = shifted_idx[np.argsort(baseline[shifted_idx])]
    magnitude = np.repeat(rng.uniform(1.5, 2.5, N_SHIFTED // 2), 2)
    direction = np.tile([1.0, -1.0], N_SHIFTED // 2)
    shift = np.zeros(n_features)
    shift[shifted_idx] = direction * magnitude

    offset = rng.uniform(-0.4, 0.4, n_samples)
    treated = (conditions == "treated").astype(float)
    noise = rng.normal(0.0, 1.0, (n_features, n_samples)) * spread[:, None]

    values = baseline[:, None] + shift[:, None] * treated[None, :] + noise + offset[None, :]
    values = np.round(values, 2)
    values[values < DETECTION_LIMIT] = np.nan

    expression = pd.DataFrame(values, index=feature_ids, columns=sample_ids)
    expression.index.name = "feature"

    samples = pd.DataFrame(
        {"sample_id": sample_ids, "condition": conditions, "replicate": replicates}
    )

    truth = pd.DataFrame(
        {
            "feature": feature_ids,
            "shifted": shift != 0,
            "true_shift": np.round(shift, 3),
            "low_signal": low_signal,
        }
    )
    return expression, samples, truth


def benjamini_hochberg(p: np.ndarray) -> np.ndarray:
    """BH-adjusted p-values. The version Module 14 has learners write by hand."""
    n = len(p)
    order = np.argsort(p)
    ranked = p[order] * n / np.arange(1, n + 1)
    # Each adjusted value is the smallest of those at its rank and above, which
    # is what keeps the adjusted values in the same order as the raw ones.
    ranked = np.minimum.accumulate(ranked[::-1])[::-1]
    adjusted = np.empty(n)
    adjusted[order] = np.minimum(ranked, 1.0)
    return adjusted


def reference_pipeline(expression: pd.DataFrame, samples: pd.DataFrame) -> pd.DataFrame:
    """The analysis the capstone asks for, done correctly.

    Filter low-signal features, median-centre each sample, Welch's t-test per
    feature, Benjamini-Hochberg across features. Returns one row per retained
    feature with its effect, raw and adjusted p, and whether it is a finding.
    """
    kept = expression[expression.mean(axis=1) >= LOW_SIGNAL_THRESHOLD]
    normalised = kept - kept.median()

    control = samples.loc[samples["condition"] == "control", "sample_id"]
    treated = samples.loc[samples["condition"] == "treated", "sample_id"]

    effect = normalised[treated].mean(axis=1) - normalised[control].mean(axis=1)
    p = stats.ttest_ind(normalised[treated], normalised[control], axis=1, equal_var=False).pvalue

    results = pd.DataFrame({"effect": effect, "p": p}, index=kept.index)
    results["p_adj"] = benjamini_hochberg(results["p"].to_numpy())
    results["significant"] = (results["p_adj"] < ALPHA) & (results["effect"].abs() >= MIN_EFFECT)
    return results


def check_invariants(expression: pd.DataFrame, samples: pd.DataFrame, truth: pd.DataFrame) -> None:
    """The promises the curriculum relies on. Raises if any is broken."""
    missing_rows = expression.isna().any(axis=1)
    flagged_low = truth.set_index("feature")["low_signal"]
    shifted = truth.set_index("feature")["shifted"]
    means = expression.mean(axis=1)

    assert missing_rows.any(), "no missing values — Module 12 needs some to find"
    assert flagged_low[missing_rows].all(), "a well-measured feature has a missing value"
    # Phrased as "not kept" rather than "below": a feature never detected in any
    # sample has a mean of NaN, and NaN < threshold is False — but so is
    # NaN >= threshold, which is the comparison the filter actually makes.
    assert not (means[flagged_low] >= LOW_SIGNAL_THRESHOLD).any(), (
        "the filter keeps a low-signal feature"
    )
    assert (means[~flagged_low] >= LOW_SIGNAL_THRESHOLD).all(), "the filter drops a good feature"
    assert not expression[~flagged_low].isna().any().any(), "gaps survive filtering"
    assert not (shifted & flagged_low).any(), "a shifted feature is low-signal"

    results = reference_pipeline(expression, samples)
    found = set(results.index[results["significant"]])
    expected = set(truth.loc[truth["shifted"], "feature"])
    assert found == expected, (
        f"the reference pipeline does not recover the ground truth exactly: "
        f"missed {sorted(expected - found)}, spurious {sorted(found - expected)}"
    )


def write(expression: pd.DataFrame, samples: pd.DataFrame, truth: pd.DataFrame) -> None:
    expression.to_csv(HERE / "expression.csv", float_format="%.2f", lineterminator="\n")
    samples.to_csv(HERE / "samples.csv", index=False, lineterminator="\n")
    truth.to_csv(HERE / "truth.csv", index=False, lineterminator="\n")
    # A small corner of the matrix for Module 12, where the file is parsed by
    # hand with split() before pandas appears. Five features and four samples is
    # enough to see the shape and small enough to check every value by eye.
    expression.iloc[:5, :4].to_csv(
        HERE / "expression_corner.csv", float_format="%.2f", lineterminator="\n"
    )
    # The reference analysis's per-feature results, for Module 15. Plotting is
    # the new idea there; recomputing 160 t-tests on the way to every plot would
    # put the previous module's work back on the critical path of this one.
    results = reference_pipeline(expression, samples)
    results.index.name = "feature"
    results[["effect", "p", "p_adj"]].to_csv(
        HERE / "results.csv", float_format="%.6g", lineterminator="\n"
    )


if __name__ == "__main__":
    expression, samples, truth = generate()
    check_invariants(expression, samples, truth)
    write(expression, samples, truth)
    print(
        f"Wrote {expression.shape[0]} features x {expression.shape[1]} samples, "
        f"{int(truth['shifted'].sum())} truly shifted, "
        f"{int(expression.isna().sum().sum())} values below detection."
    )
